// Trasforma l'evento inviato dal backend NeuroParty in oggetto + testo per la mail.
// Struttura in ingresso: { event, timestamp, source, data } (vedi README del backend).
const b = $input.first().json.body;
const d = b.data || {};
const eur = (n) => Number(n || 0).toLocaleString('it-IT', { style: 'currency', currency: 'EUR' });
const rsvp = { CONFIRMED: 'confermato', PENDING: 'in attesa', DECLINED: 'declinato' };
let subject = null;
let text = '';

switch (b.event) {
  case 'guest.created': {
    const g = d.guest, s = d.summary || {};
    subject = `Nuovo RSVP: ${g.fullName} (${g.guestsCount} pers., ${rsvp[g.rsvpStatus] || g.rsvpStatus})`;
    text = `${g.fullName} - ${g.category}\nStato: ${rsvp[g.rsvpStatus] || g.rsvpStatus}, persone: ${g.guestsCount}\nEsigenze alimentari: ${g.dietaryNotes || '-'}\nContatto: ${g.contactInfo || '-'}\n\nCoperti confermati finora: ${s.covers} (${s.pendingCovers} in attesa)`;
    break;
  }
  case 'guest.updated': {
    const g = d.guest, s = d.summary || {};
    if (!d.changes || !('rsvpStatus' in d.changes)) return []; // solo i cambi di stato RSVP
    subject = `RSVP aggiornato: ${g.fullName} -> ${rsvp[g.rsvpStatus] || g.rsvpStatus}`;
    text = `${g.fullName} ora e' ${rsvp[g.rsvpStatus] || g.rsvpStatus} (${g.guestsCount} pers.).\n\nCoperti confermati finora: ${s.covers} (${s.pendingCovers} in attesa)`;
    break;
  }
  case 'bus.booked': {
    const k = d.booking, bus = d.bus || {};
    subject = `Navetta: ${k.passengerName} ha prenotato ${k.seatsCount} posti`;
    text = `${k.passengerName} - ${k.seatsCount} posti\nFermata: ${k.pickupStop || '-'}\nRitorno: ${k.returnTripWanted ? 'si' : 'no'}\nTelefono: ${k.contactPhone || '-'}\nNote: ${k.notes || '-'}\n\nPosti prenotati: ${bus.bookedSeats}/${bus.maxSeats} (liberi ${bus.availableSeats})`;
    break;
  }
  case 'gift.contributed': {
    const c = d.contribution, t = d.target || {};
    subject = `Regalo: ${eur(c.amount)} da ${c.donorName} per ${c.targetGraduateName}`;
    text = `${c.donorName} ha contribuito con ${eur(c.amount)} (${c.paymentMethod}) per ${c.targetGraduateName}.\nNota: ${c.note || '-'}\n\nRaccolti finora: ${eur(t.collectedAmount)} su ${eur(t.targetAmount)}`;
    break;
  }
  case 'test':
    subject = 'Test collegamento n8n riuscito';
    text = d.message || 'ok';
    break;
  default:
    return []; // wish.created, photo.uploaded, notification.*: nessuna mail
}

return [{ json: { event: b.event, subject, text, raw: b } }];
